import React from "react";
import { Link } from "react-router-dom";

export default function Footer() {
  return (
    <footer style={{ background: "var(--deep)", color: "rgba(255,255,255,.45)", padding: "48px 0 32px", fontSize: 13 }}>
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "0 40px" }}>
        <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr", gap: 40, marginBottom: 40 }}>
          <div>
            <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 22, color: "white", marginBottom: 12 }}>
              Room<span style={{ color: "var(--gold)" }}>ly</span>
            </div>
            <p style={{ fontSize: 13, lineHeight: 1.7, color: "rgba(255,255,255,.4)", maxWidth: 240 }}>
              Egypt's most trusted room booking platform. Find your perfect stay with confidence.
            </p>
          </div>
          {[
            { title: "Platform", links: ["Explore Rooms", "How it Works", "Pricing", "Safety"] },
            { title: "Company",  links: ["About Us", "Careers", "Press", "Blog"] },
            { title: "Support",  links: ["Help Center", "Contact Us", "Terms", "Privacy"] },
          ].map(col => (
            <div key={col.title}>
              <h5 style={{ color: "rgba(255,255,255,.85)", fontWeight: 600, fontSize: 13, marginBottom: 16 }}>{col.title}</h5>
              {col.links.map(l => (
                <a key={l} href="#" style={{ display: "block", color: "rgba(255,255,255,.4)", textDecoration: "none", marginBottom: 8, transition: "color .15s" }}
                  onMouseEnter={e => e.target.style.color = "rgba(255,255,255,.8)"}
                  onMouseLeave={e => e.target.style.color = "rgba(255,255,255,.4)"}
                >{l}</a>
              ))}
            </div>
          ))}
        </div>
        <div style={{ borderTop: "1px solid rgba(255,255,255,.08)", paddingTop: 24, display: "flex", justifyContent: "space-between" }}>
          <span>© 2025 Roomly. All rights reserved.</span>
          <span>Built for Egypt 🇪🇬</span>
        </div>
      </div>
    </footer>
  );
}
